  reg [1:0] state; 
  reg [7:0] spad_needed_len; 
  reg [1:0] wBurst; 
  reg [2:0] wSize; 
  reg [5:0] iBID; 
  reg [16:0] iAddr; 
  wire  _T_2 = s_axi_w_ready & s_axi_w_valid; 
  wire [16:0] NextAddr = NextAddr_m_NextAddr; 
  wire  _s_axi_w_ready_T = state == 2'h1; 
  SramAddrGen NextAddr_m ( 
    .CurAddr(NextAddr_m_CurAddr),
    .Len(NextAddr_m_Len),
    .Size(NextAddr_m_Size),
    .Burst(NextAddr_m_Burst),
    .NextAddr(NextAddr_m_NextAddr)
  );
  assign s_axi_aw_ready = state == 2'h0; 
  assign s_axi_w_ready = state == 2'h1; 
