  assign NextAddr_m_Len = spad_needed_len; 
  assign NextAddr_m_Size = wSize; 
  assign NextAddr_m_Burst = wBurst; 
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      state <= 2'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin 
        state <= 2'h1; 
      end
    end else if (2'h1 == state) begin 
      if (_T_2) begin 
        if (s_axi_w_bits_last) begin 
          state <= 2'h2;
        end
      end
    end else if (2'h2 == state) begin 
      if (s_axi_b_ready) begin
        state <= 2'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      spad_needed_len <= 8'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin
        spad_needed_len <= s_axi_aw_bits_len;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      wBurst <= 2'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin
        wBurst <= s_axi_aw_bits_burst;
      end else begin
        wBurst <= 2'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      wSize <= 3'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin
        wSize <= s_axi_aw_bits_size;
      end else begin
        wSize <= 3'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      iBID <= 6'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin
        iBID <= s_axi_aw_bits_id;
      end else begin
        iBID <= 6'h0;
      end
    end
  end
  always @(posedge aclk or posedge reset) begin
    if (reset) begin 
      iAddr <= 17'h0; 
    end else if (2'h0 == state) begin 
      if (s_axi_aw_valid) begin 
        iAddr <= s_axi_aw_bits_addr; 
      end
    end else if (2'h1 == state) begin 
