module ARITH(
  input  [2:0]  io_config, 
  input  [31:0] io_in_1, 
  input  [31:0] io_in_0, 
  output        io_out_1, 
  output [31:0] io_out_0 
);
  wire [31:0] _op1_T_2 = io_config[1] ? 32'hffffffff : 32'h0; 
  wire [31:0] op1 = io_in_0 ^ _op1_T_2; 
  wire [31:0] _op2_T_2 = io_config[2] ? 32'hffffffff : 32'h0; 
  wire [31:0] op2 = io_in_1 ^ _op2_T_2; 
  wire  carry = io_config[2] | io_config[1]; 
  wire [31:0] _sum_T_1 = op1 + op2; 
  wire [31:0] _GEN_0 = {{31'd0}, carry}; 
  wire [31:0] sum = _sum_T_1 + _GEN_0; 
  assign io_out_1 = sum[31] ^ io_config[0]; 
  assign io_out_0 = _sum_T_1 + _GEN_0; 
endmodule
