  assign io_c_out = ~io_c0 & ~io_a & io_b | ~io_c0 & io_a & ~io_b | io_c1 & io_c0 & ~io_a & ~io_b | io_c0 & io_a & io_b
     | ~io_c1 & ~io_c0 & io_b; 
endmodule
