// End of auto-generated section

    always @(*) begin
        case(segment)
            24'd0: begin A1 = {1'b0, f[21:1]}; A2 = {4'b1111, neg_18}; A3 = {6'b111111, neg_16}; end
            24'd1: begin A1 = {1'b0, f[21:1]}; A2 = {3'b111, neg_19}; A3 = {7'b0000000, f[21:7]}; end
